package app.space.notes.runtime;
import android.graphics.*;
import android.view.*;
import android.widget.FrameLayout;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import static org.junit.Assert.*;
/** Pixel assertions exercise real Android paths, brush histories and export, not source strings. */
public class DrawingToolsTest {
 private void onMain(Runnable action){InstrumentationRegistry.getInstrumentation().runOnMainSync(action);}
 private DrawingPad paper(){android.content.Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();DrawingPad pad=new DrawingPad(c);new FrameLayout(c).addView(pad);pad.measure(View.MeasureSpec.makeMeasureSpec(1024,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(768,View.MeasureSpec.EXACTLY));pad.layout(0,0,1024,768);pad.loaded(null);return pad;}
 private void draw(DrawingPad pad,float x,float y,float endX,float endY){long now=android.os.SystemClock.uptimeMillis();for(int i=0;i<3;i++){MotionEvent e=MotionEvent.obtain(now,now+i*20,new int[]{0,2,1}[i],i==0?x:endX,i==0?y:endY,0);assertTrue(pad.onTouchEvent(e));e.recycle();}}
 @Test public void rectangleAndOvalAreOutlinesNotFilledBlocks(){onMain(()->{DrawingPad p=paper();p.tool(5);p.width(8);draw(p,100,100,600,500);Bitmap b=p.snapshot();assertEquals(Color.BLACK,b.getPixel(300,100));assertEquals(Color.WHITE,b.getPixel(300,300));b.recycle();p.undo();p.tool(6);draw(p,100,100,600,500);b=p.snapshot();assertEquals(Color.BLACK,b.getPixel(350,100));assertEquals(Color.WHITE,b.getPixel(350,300));b.recycle();});}
 @Test public void brushWidthAndColourAreCapturedPerStroke(){onMain(()->{DrawingPad p=paper();p.width(16);p.color(Color.RED);draw(p,100,100,700,100);p.color(Color.BLUE);p.width(2);draw(p,100,200,700,200);Bitmap b=p.snapshot();assertEquals(Color.RED,b.getPixel(400,105));assertEquals(Color.BLUE,b.getPixel(400,200));assertEquals(Color.WHITE,b.getPixel(400,205));b.recycle();});}
 @Test public void highlighterAndEraserHaveDifferentPixelSemantics(){onMain(()->{DrawingPad p=paper();p.tool(2);p.color(Color.RED);draw(p,100,100,700,100);Bitmap b=p.snapshot();int ink=b.getPixel(400,100);assertEquals(255,Color.red(ink));assertTrue(Color.green(ink)>0 && Color.green(ink)<255);b.recycle();p.tool(3);draw(p,100,100,700,100);b=p.snapshot();assertEquals(Color.WHITE,b.getPixel(400,100));b.recycle();p.undo();b=p.snapshot();assertEquals(ink,b.getPixel(400,100));b.recycle();});}
 @Test public void clearCanBeUndoneAndRedoDoesNotChangeOtherStrokes(){onMain(()->{DrawingPad p=paper();draw(p,100,100,700,100);p.clear();Bitmap b=p.snapshot();assertEquals(Color.WHITE,b.getPixel(400,100));b.recycle();p.undo();b=p.snapshot();assertEquals(Color.BLACK,b.getPixel(400,100));b.recycle();p.redo();b=p.snapshot();assertEquals(Color.WHITE,b.getPixel(400,100));assertEquals(1024,b.getWidth());assertEquals(768,b.getHeight());b.recycle();});}
 @Test public void detailedTransparentImagesAreReducedInsteadOfRefused()throws Exception{
  Bitmap original=Bitmap.createBitmap(1600,1200,Bitmap.Config.ARGB_8888);int[] pixels=new int[1600*1200];java.util.Random noise=new java.util.Random(7);for(int i=0;i<pixels.length;i++)pixels[i]=noise.nextInt();original.setPixels(pixels,0,1600,0,0,1600,1200);int first=original.getPixel(0,0);try{app.space.notes.domain.NoteImage image=NoteImageFiles.encode(original,"Image");assertTrue(java.util.Base64.getDecoder().decode(image.data).length<=900*1024);assertTrue(image.width<1600);assertEquals(first,original.getPixel(0,0));Bitmap saved=NoteImageFiles.decode(image);assertNotNull(saved);saved.recycle();}finally{original.recycle();}
 }
 private MotionEvent two(long start,int time,int action,float span){MotionEvent.PointerProperties[] props={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] coords={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i].x=512+(i==0?-span/2:span/2);coords[i].y=384;coords[i].pressure=1;coords[i].size=1;}return MotionEvent.obtain(start,start+time,action,2,props,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);}
 @Test public void twoFingerZoomChangesViewportButNotExportOrHistory(){onMain(()->{DrawingPad p=paper();draw(p,100,100,700,100);Bitmap original=p.snapshot();long revision=p.revision(),now=android.os.SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,0,412,384,0);p.onTouchEvent(down);down.recycle();MotionEvent e=two(now,20,MotionEvent.ACTION_POINTER_DOWN|(1<<8),200);p.onTouchEvent(e);e.recycle();for(int i=0;i<4;i++){e=two(now,40+i*20,MotionEvent.ACTION_MOVE,400+i*160);p.onTouchEvent(e);e.recycle();}e=two(now,140,MotionEvent.ACTION_POINTER_UP|(1<<8),880);p.onTouchEvent(e);e.recycle();e=MotionEvent.obtain(now,now+160,MotionEvent.ACTION_UP,72,384,0);p.onTouchEvent(e);e.recycle();assertEquals(revision,p.revision());try{java.lang.reflect.Field zoom=DrawingPad.class.getDeclaredField("zoom");zoom.setAccessible(true);assertTrue("Creation zoom is bounded at five times",zoom.getFloat(p)<=5f);}catch(ReflectiveOperationException unavailable){throw new AssertionError(unavailable);}Bitmap exported=p.snapshot();assertTrue(original.sameAs(exported));Bitmap presented=Bitmap.createBitmap(1024,768,Bitmap.Config.ARGB_8888);p.draw(new Canvas(presented));assertFalse("Pinch must actually change the displayed paper",original.sameAs(presented));p.fit();Bitmap fitted=Bitmap.createBitmap(1024,768,Bitmap.Config.ARGB_8888);p.draw(new Canvas(fitted));assertTrue(original.sameAs(fitted));original.recycle();exported.recycle();presented.recycle();fitted.recycle();});}
 @Test public void mediaStoreImageImportsOwnPixelsAndSurvivesSourceDeletion()throws Exception{
  android.content.Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();OfflineOcr.requireLocal(android.net.Uri.parse("content://com.android.providers.media.documents/document/image%3A1"));
  if(android.os.Build.VERSION.SDK_INT<29)return; // API26 real stream coverage is the SAF fixture; scoped own-media insertion starts at 29.
  android.content.ContentValues values=new android.content.ContentValues();values.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME,"MyNotes-image-test-"+java.util.UUID.randomUUID()+".png");values.put(android.provider.MediaStore.Images.Media.MIME_TYPE,"image/png");values.put("is_pending",1);android.net.Uri uri=c.getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);assertNotNull(uri);
  try{Bitmap pixels=Bitmap.createBitmap(32,24,Bitmap.Config.ARGB_8888);pixels.eraseColor(Color.GREEN);try(java.io.OutputStream out=c.getContentResolver().openOutputStream(uri)){assertTrue(pixels.compress(Bitmap.CompressFormat.PNG,100,out));}pixels.recycle();values.clear();values.put("is_pending",0);c.getContentResolver().update(uri,values,null,null);app.space.notes.domain.NoteImage image=NoteImageFiles.importImage(c,uri);assertEquals(32,image.width);assertEquals(24,image.height);assertEquals(1,c.getContentResolver().delete(uri,null,null));uri=null;Bitmap saved=NoteImageFiles.decode(image);assertNotNull(saved);assertEquals(Color.GREEN,saved.getPixel(10,10));saved.recycle();}finally{if(uri!=null)c.getContentResolver().delete(uri,null,null);}
 }
 @Test public void portraitCanvasUsesFullHeightAndKeepsLegacyBitmapProportions(){onMain(()->{android.content.Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();DrawingPad p=new DrawingPad(c);new FrameLayout(c).addView(p);p.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));p.layout(0,0,400,800);Bitmap legacy=Bitmap.createBitmap(1024,768,Bitmap.Config.ARGB_8888);legacy.eraseColor(Color.WHITE);legacy.setPixel(100,100,Color.RED);p.loaded(legacy);assertEquals(800,p.getHeight());Bitmap b=p.snapshot();assertEquals(1024,b.getWidth());assertEquals(2048,b.getHeight());assertEquals(Color.RED,b.getPixel(100,100));assertEquals(Color.WHITE,b.getPixel(100,1000));b.recycle();draw(p,20,600,300,600);b=p.snapshot();assertEquals(Color.BLACK,b.getPixel(400,1536));b.recycle();p.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY));p.layout(0,0,1200,400);p.tool(4);draw(p,1100,100,1100,300);b=p.snapshot();assertEquals(Color.BLACK,b.getPixel(939,171));assertEquals(Color.BLACK,b.getPixel(400,1536));Bitmap shown=Bitmap.createBitmap(1200,400,Bitmap.Config.ARGB_8888);p.draw(new Canvas(shown));assertEquals(Color.BLACK,shown.getPixel(1100,200));p.fit();Bitmap fitted=Bitmap.createBitmap(1200,400,Bitmap.Config.ARGB_8888);p.draw(new Canvas(fitted));assertEquals(Color.WHITE,fitted.getPixel(1100,200));Bitmap after=p.snapshot();assertTrue(b.sameAs(after));shown.recycle();fitted.recycle();after.recycle();b.recycle();});}
 @Test public void gridIsAViewportGuideAndNeverChangesExportOrUndoHistory(){onMain(()->{DrawingPad p=paper();draw(p,100,100,700,100);Bitmap before=p.snapshot();long revision=p.revision();p.grid(true);Bitmap after=p.snapshot(),shown=Bitmap.createBitmap(1024,768,Bitmap.Config.ARGB_8888);p.draw(new Canvas(shown));assertTrue(before.sameAs(after));assertFalse(before.sameAs(shown));assertEquals(revision,p.revision());p.grid(false);Bitmap hidden=Bitmap.createBitmap(1024,768,Bitmap.Config.ARGB_8888);p.draw(new Canvas(hidden));assertTrue(before.sameAs(hidden));before.recycle();after.recycle();shown.recycle();hidden.recycle();});}
 @Test public void historyAvailabilityNotifiesControlsForStrokeUndoRedoAndSaving(){onMain(()->{DrawingPad p=paper();java.util.concurrent.atomic.AtomicInteger updates=new java.util.concurrent.atomic.AtomicInteger();p.onStateChanged(updates::incrementAndGet);assertFalse(p.canUndo());assertFalse(p.canRedo());int before=updates.get();draw(p,100,100,700,100);assertTrue(updates.get()>before);assertTrue(p.canUndo());assertFalse(p.canRedo());p.saving(true);assertFalse(p.canUndo());p.saving(false);p.undo();assertFalse(p.canUndo());assertTrue(p.canRedo());p.redo();assertTrue(p.canUndo());assertFalse(p.canRedo());});}
 @Test public void extremeLegacyAspectRatioStaysBoundedAndDoesNotStretchPixels(){onMain(()->{Bitmap narrow=Bitmap.createBitmap(1,1600,Bitmap.Config.ARGB_8888);narrow.eraseColor(Color.BLUE);DrawingPad p=new DrawingPad(InstrumentationRegistry.getInstrumentation().getTargetContext());p.loaded(narrow);p.measure(View.MeasureSpec.makeMeasureSpec(256,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(768,View.MeasureSpec.EXACTLY));p.layout(0,0,256,768);Bitmap image=p.snapshot();assertEquals(4096,image.getHeight());assertTrue(Color.blue(image.getPixel(512,2000))>160);assertTrue(Color.red(image.getPixel(512,2000))<100);assertEquals(Color.WHITE,image.getPixel(200,2000));image.recycle();narrow.recycle();});}
 @Test public void copiedDrawingUsesReadablePngUriRatherThanTextOrUiPixels()throws Exception{
  android.app.Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();android.content.Context c=instrumentation.getTargetContext();android.app.Activity activity=instrumentation.startActivitySync(new android.content.Intent(c,app.space.notes.NotesActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));Bitmap bitmap=Bitmap.createBitmap(32,24,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE);android.net.Uri uri=DrawingClipboard.write(c,bitmap);assertEquals("image/png",c.getContentResolver().getType(uri));try(java.io.InputStream in=c.getContentResolver().openInputStream(uri)){Bitmap decoded=BitmapFactory.decodeStream(in);assertNotNull(decoded);assertTrue(bitmap.sameAs(decoded));decoded.recycle();}
  java.util.concurrent.CountDownLatch foreground=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean ended=new java.util.concurrent.atomic.AtomicBoolean();onMain(()->activity.getWindow().getDecorView().post(new Runnable(){public void run(){if(ended.get())return;if(activity.hasWindowFocus())foreground.countDown();else activity.getWindow().getDecorView().postDelayed(this,25);}}));try{assertTrue("A real foreground Notes window is required before reading the system clipboard; inspect retained window/ANR diagnostics",foreground.await(12,java.util.concurrent.TimeUnit.SECONDS));}finally{ended.set(true);}
  android.content.ClipData[] previous={null};onMain(()->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)c.getSystemService(android.content.Context.CLIPBOARD_SERVICE);previous[0]=clipboard.getPrimaryClip();DrawingClipboard.publish(c,uri);android.content.ClipData clip=clipboard.getPrimaryClip();assertNotNull(clip);assertTrue(clip.getDescription().hasMimeType("image/png"));assertEquals(uri,clip.getItemAt(0).getUri());if(previous[0]!=null)clipboard.setPrimaryClip(previous[0]);else if(android.os.Build.VERSION.SDK_INT>=28)clipboard.clearPrimaryClip();else clipboard.setPrimaryClip(android.content.ClipData.newPlainText("",""));});assertEquals(1,c.getContentResolver().delete(uri,null,null));bitmap.recycle();onMain(activity::finish);
 }
 @Test public void draftChecksumMatchesPngBeforeAttachmentResizing()throws Exception{Bitmap b=Bitmap.createBitmap(1024,2048,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);String expected=DrawingClipboard.digest(b);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));assertEquals(expected,DrawingClipboard.digest(new java.io.ByteArrayInputStream(out.toByteArray())));app.space.notes.domain.NoteImage image=NoteImageFiles.encode(b,"Drawing");assertEquals(1600,image.height);assertNotEquals(expected,DrawingClipboard.digest(new java.io.ByteArrayInputStream(java.util.Base64.getDecoder().decode(image.data))));b.recycle();}

}
